    "context_text_1": {
      "type": "Text",
      "props": {
        "text": "Your budget of €2,500 for accommodation and activities for four people over seven days (approximately €357 per day) is quite tight for Rome in July. To stay within this, focus on budget-friendly accommodation (e.g., apartment rentals slightly outside the main tourist areas), utilize public transport, enjoy street food and picnics, and prioritize free attractions while selectively choosing paid ones.",
        "variant": "body"
      },
      "children": []
    },
    "context_text_2": {
      "type": "Text",
      "props": {
        "text": "Flights are not included in the budget.",
        "variant": "body"
      },
      "children": []
    },
    "context_text_3": {
      "type": "Text",
      "props": {
        "text": "Pre-booking tickets for major attractions is highly recommended, especially for July travel.",
